INSERT INTO public.training_library (age_group, training_number, exercises)
VALUES
('O11', 1, '{"session_a": [{"type": "warming_up", "title": "DRIE IS TEVEEL", "content": "De spelers vormen naast elkaar staande tweetallen verspreid over\nhet hele vak. Twee spelers, 1 loper en 1 tikker vormen geen\ntweetal. De loper probeert de tikker te ontlopen en kan zich\ndaarbij vrijspelen door naast een tweetal te gaan staan.\nDe speler die aan de andere buitenkant komt te staan wordt\ndaardoor de nieuwe loper, die getikt moet worden.\nOpgelet!\nEen getikte speler wordt direct de nieuwe tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 12 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- De spelers moeten stil op hun plek blijven\nstaan"}, {"type": "techniek", "title": "STAP 2.5 B: AANNEMEN-OPENEN, TOT 45º IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- Idem als beschreven bij A, etc.\nC. Speler 1 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nD. Speler 3 speelt naar speler 2\n- Idem als beschreven bij A, etc.\nE. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan en dribbelt met de bal naar de volgende pylon,\netc.\nF. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, maar nu in tegengestelde richting uitvoeren.\n- Idem, met links aannemen en met links spelen.\nMaterialen\nAantal spelers: 6-10\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O11', 2, '{"session_a": [{"type": "warming_up", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 B: AANBIEDEN, TOT 45º IN DRIEHOEKSVORM (1)", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich opengedraaid \"naar links\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 1\n- speler 1 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 1, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(5 : 3) OEFENING 1", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}], "session_b": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BUITEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 5B)\n- Akka (buiten-binnen) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie in uitvoering:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 5) en\nAkka (buiten-binnen) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wisselt, na de pass op speler 3, van\nplaats met speler 2. Vervolgens wisselt speler 3\nvan plaats met speler 1, nadat hij de oefening in\ntegenovergestelde richting en met het ander\nbeen heeft uitgevoerd, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om in één van de drie aan de overkant van\nhet vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 20m bij 25m\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-junioren: 35m bij 40m\nB-,A-junioren: 40m bij 45m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler).\n- het rekening houden met omschakeling bij\nbalverovering\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes (passeeractie of overspelen)\ngemaakt worden\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O11', 3, '{"session_a": [{"type": "warming_up", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 B: KAATSEN-OPENEN, TOT 45º IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nD. Speler 3 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 2.\nE. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich opengedraaid \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan en dribbelt met de bal naar de volgende pylon,\netc.\nF. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\nIdem, maar nu in tegengestelde richting uitvoeren en met links\nuitvoeren.\nMaterialen\nAantal spelers: 6-10\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "STAP 2.3 A: KOPPEN (RECHT) VANUIT EEN STAANDE POSITIE", "content": "Staande oefening met 2-tallen, waarbij speler 1 de bal aangooit\nen speler 2 vanuit een \"spreidschrede\" stand de bal terugkopt.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal recht terug , etc.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-pupillen: 3 m\nDoordraaien:\nWisselen van functie naar eigen inzicht.\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal recht aangegooid en\nwordt daardoor gedwongen om de bal ook\nrecht terug te koppen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "UIT DE RUG", "content": "Oefeningen, waarbij de spelers voor elkaar staan. De voorste speler staat hierbij\nin een vak van 2 bij 3 meter.\nDe achterste speler probeert, door plotseling te versnellen, uit de rug van de\nvoorste speler te komen en zonder getikt te worden de finishlijn te behalen.\nOpgelet!\nHet is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\nLater, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 6\nAantal ballen: 0\nOrganisatie:\nDe spelers staan voor elkaar. Bij deze oefening ligt het initiatief ligt bij de\nachterste speler."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Sleep (Stap 4B)\n- Uitstappen meenemen (Stap 5B)\n- Akka (binnen-voor) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie in uitvoering:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 5), Sleep (Stap 4) en Akka (binnen-voor) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wisselt, na de pass op speler 3, van\nplaats met speler 2. Vervolgens wisselt speler 3\nvan plaats met speler 1, nadat hij de oefening in\ntegenovergestelde richting en met het ander\nbeen heeft uitgevoerd, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O11', 4, '{"session_a": [{"type": "warming_up", "title": "C. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.7 A: AANNEMEN (MET BOVENBEEN) EN SPELEN (HEEN TERUG)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op bovenbeenhoogte met een\nboog naar speler 2.\nB. Speler 2 speelt naar speler 1\n- Speler 2 neemt de bal met het rechter bovenbeen aan en speelt\nde bal binnenkant van de rechtervoet terug, etc.\nVariatie in uitvoering:\nIdem, met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAannemen:\n- Bij het aannemen met het bovenbeen\nsoepel en flexibel met de bal meegaan en\nzodoende bal \"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan, op een onderlinge afstand van 2 meter. Aan de ene\nkant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\néén van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- als de speler de ander voor de vrije zone\nkan tikken dan heeft die een punt. Speel een\npotje tot de vijf.\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer er een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen, dus\nspelen met de ''rrrrr''."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (ANDERE)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA.Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 5B)\n- Akka (binnen-buiten) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 5) en Akka (binnen-buiten) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 komt, na de pass op speler 3, op een\nplaats te staan schuin tegenover speler 3.\nVervolgens neemt speler 2 de plaats in van\nspeler 1. Speler 3 voert nu de oefening, met het\nander been, in tegenovergestelde richting uit,\nenz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nOPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD\nMethodiek\nD.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O11', 5, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.5 B: AANNEMEN-OPENEN, TOT 45º IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- Idem als beschreven bij A, etc.\nC. Speler 1 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nD. Speler 3 speelt naar speler 2\n- Idem als beschreven bij A, etc.\nE. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan en dribbelt met de bal naar de volgende pylon,\netc.\nF. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, maar nu in tegengestelde richting uitvoeren.\n- Idem, met links aannemen en met links spelen.\nMaterialen\nAantal spelers: 6-10\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(5 : 3) OEFENING 2", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "LIJNDRIBBEL 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna de bal over de lijn aan de overkant van het\nvak te dribbelen.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren."}], "session_b": [{"type": "test", "title": "SPEEDLADDER (3)", "content": "Is een oefening, waarbij de zijwaartse en voorwaartse vormen\nworden gecombineerd en aangeleerd in de speedladder. De\noefening is opgebouwd van grove motoriek naar de fijne motoriek.\nDat wil zeggen binnen de looptraining, er wordt gewerkt van een\nskipping naar skipping 45 graden en vervolgens naar kort\nvoetenwerk.\nStap 1: Twee voetjes in het raam plaatsen, één voetje eruit\nplaatsen.\nStap 2: Twee voetjes in het raam plaatsen, twee voetjes eruit\nplaatsen. (3 pasjes)\nStap 3: Eén voetjes in het raam plaatsen, twee voetjes eruit\nplaatsen. (kruisbeweging)\nLet op!\nDeze vormen kunnen pas worden aangeleerd wanneer\nspeedladder (1) en speedladder (2) beheerst worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BUITEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 5B)\n- Akka (buiten-binnen) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie in uitvoering:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 5) en\nAkka (buiten-binnen) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wisselt, na de pass op speler 3, van\nplaats met speler 2. Vervolgens wisselt speler 3\nvan plaats met speler 1, nadat hij de oefening in\ntegenovergestelde richting en met het ander\nbeen heeft uitgevoerd, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET WEERSTAND (2)", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Schaar (Stap 5B)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan komt een tegenstander (speler 2) frontaal\nop hem inlopen. Hij passeert vervolgens de tegenstander met één\nvan de bovengenoemde technieken.\nC. Daarna controleert hij de bal en rond vervolgens af op het doel\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan en\nspeler 1 neemt de taak over van speler 2.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Speler 1 neemt de taak over van speler 2.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "techniek", "title": "POORTJESVOETBAL 5 TEGEN 5", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van elk 5 spelers\ndie op een speelveld tegenover elkaar staan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren door het poortje van één van de tegenstanders.\nOpgelet:\n- het team dat scoort behoudt balbezit, maar mag niet tweemaal\nachter elkaar in hetzelfde doeltje scoren.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O11', 6, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\n- Kappen buitenkant voet (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- idem, met rechts aannemen en met links spelen.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.3 B: KOPPEN (SCHUIN) VANUIT EEN STAANDE POSITIE", "content": "Staande oefening met 2-tallen, waarbij speler 1 de bal aangooit\nen speler 2 vanuit een \"spreidschrede\" stand de bal schuin\nterugkopt.\nA. Speler 1 speelt naar speler 2\n- Speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- Speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\nIdem, in tegengestelde richting met een aangooi vanaf de ander\nkant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-pupillen: 3 m\nDoordraaien:\nWisselen van functie naar eigen inzicht.\nAanwijzingen\n- Bovenlichaam naar achteren, kin op de\nborst .\n- Armen voor je houden.\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- Speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "UIT DE RUG", "content": "Oefeningen, waarbij de spelers voor elkaar staan. De voorste speler staat hierbij\nin een vak van 2 bij 3 meter.\nDe achterste speler probeert, door plotseling te versnellen, uit de rug van de\nvoorste speler te komen en zonder getikt te worden de finishlijn te behalen.\nOpgelet!\nHet is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\nLater, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 6\nAantal ballen: 0\nOrganisatie:\nDe spelers staan voor elkaar. Bij deze oefening ligt het initiatief ligt bij de\nachterste speler."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Sleep (Stap 4B)\n- Uitstappen meenemen (Stap 5B)\n- Akka (binnen-voor) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie in uitvoering:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 5), Sleep (Stap 4) en Akka (binnen-voor) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wisselt, na de pass op speler 3, van\nplaats met speler 2. Vervolgens wisselt speler 3\nvan plaats met speler 1, nadat hij de oefening in\ntegenovergestelde richting en met het ander\nbeen heeft uitgevoerd, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (2 : 1)", "content": "REGELS:\n• Twee aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• Direct na verovering van de bal moet de verdediger wisselen\nvan taak met de aanvaller van wie hij de bal heeft veroverd.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 3\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het vrijlopen en aanspeelbaar zijn, zonder\nbal\n• het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n• het altijd in beweging zijn van de bal en de\nspeler\n• het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n• het vragen om de bal\n• het nacoachen van de bal/ pass\nVERDEDIGER COACHEN OP:\n• het rekening houden met een goed zicht op\nde posities van de aanvallers\n• het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\nKANTELEN VOETBAL 5 TEGEN 5\nMethodiek\nDeze oefening wordt uitgevoerd met 2 teams van elk 5 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 14\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O11', 7, '{"session_a": [{"type": "warming_up", "title": "OVERSTEEK SPEL", "content": "Alle spelers staan met de bal aan de voet aan één kant van het\nveld en één speler staat zonder bal in het midden. Op een teken\nvan de trainer mogen de spelers proberen het veld over te steken.\nDe tikker moet vervolgens proberen de ballen van de spelers\nbuiten het veld te schieten.\nDe spelers van een weggeschoten bal gaan ook in het midden\nstaan om de bal af te pakken.\nVariatie:\n- De spelers moeten zelf hun weggetrapte bal ophalen en weer bij\nde groep aansluiten.\n- Weggeschoten bal ophalen en dan wachten om te zien wie er\nover blijft. De winnaar mag de nieuwe tikker zijn of aanwijzen.\n- Twee of meerdere afpakkers.\nMaterialen\nTijd: 10-15 min\nPylonen:\n4 pylonen om het speelveld uit te zetten.\n2 pylonen/hoedjes om de middenlijn uit te zetten.\nBallen: iedere speler een bal op de tikker na die\nde ballen gaat afpakken.\nAanwijzingen\n- Zorg dat de spelers de bal dicht bij zich\nhouden zodat ze de bal goed kunnen sturen.\n- Laat de spelers telkens op het teken van de\ntrainer starten."}, {"type": "techniek", "title": "STAP 2.6 B: KAATSEN-OPENEN, TOT 45º IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nD. Speler 3 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 2.\nE. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich opengedraaid \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan en dribbelt met de bal naar de volgende pylon,\netc.\nF. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\nIdem, maar nu in tegengestelde richting uitvoeren en met links\nuitvoeren.\nMaterialen\nAantal spelers: 6-10\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (ANDERE)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA.Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 5B)\n- Akka (binnen-buiten) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 5) en Akka (binnen-buiten) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 komt, na de pass op speler 3, op een\nplaats te staan schuin tegenover speler 3.\nVervolgens neemt speler 2 de plaats in van\nspeler 1. Speler 3 voert nu de oefening, met het\nander been, in tegenovergestelde richting uit,\nenz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD\nMethodiek\nD.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O11', 8, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.7 A: AANNEMEN (MET BOVENBEEN) EN SPELEN (HEEN TERUG)\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op bovenbeenhoogte met een\nboog naar speler 2.\nB. Speler 2 speelt naar speler 1\n- Speler 2 neemt de bal met het rechter bovenbeen aan en speelt\nde bal binnenkant van de rechtervoet terug, etc.\nVariatie in uitvoering:\nIdem, met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAannemen:\n- Bij het aannemen met het bovenbeen\nsoepel en flexibel met de bal meegaan en\nzodoende bal \"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(5 : 3) OEFENING 2", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (2)", "content": "Is een oefening, waarbij de zijwaartse vormen worden aangeleerd\nover de stokken. De oefening is opgebouwd van grove motoriek\nnaar de fijne motoriek. Dat wil zeggen binnen de looptraining, er\nwordt gewerkt van een skipping naar skipping 45 graden en\nvervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de andere stokken worden gelopen met één voet\ntussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden zijwaarts genomen en vervolgens wordt er met\ntwee voeten teruggestapt, de andere stokken worden gelopen\nmet één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden zijwaarts genomen en vervolgens\nwordt er met twee voeten teruggestapt, de andere stokken\nworden gelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 3 komt, als tegenstander, ter hoogte van het midden van\nde middelste pylonen inlopen op speler 2.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen- buitenkant wegdraai (Stap 5)\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar de overkant.\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 5),\nKappen buitenkant voet (Stap 4) en Binnen buiten wegdraai (Stap\n5).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\n- Speler 1 blijft, na de pass op speler 2, staan.\nSpeler 2 dribbelt naar de plek ter hoogte van de\noverstaande pylonen en neemt de plek van\nspeler 3 in. Speler 3 gaat in het midden staan.\n- Speler 2 voert nu de oefening, met het ander\nbeen, in tegenovergestelde richting uit, enz..\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET WEERSTAND", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\n- Binnen-buitenkant wegdraai (Stap 5)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op de aanbiedende speler 2 te\npassen(deze heeft een verdediger, speler 3,in de rug).\nB. Speler 2 ontvangt de bal en passeert vervolgens met één van\nde bovengenoemde technieken de in zijn rug staande verdediger.\nC. Daarna dribbelt hij richting doel om vervolgens hierop af te\nronden.\nD. Speler 3 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 6,7,8,9 en 10 voeren dezelfde oefening uit op het\nandere doel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 neemt de taak over van speler 3.\n- Speler 3 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "techniek", "title": "POORTJESVOETBAL 5 TEGEN 5", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van elk 5 spelers\ndie op een speelveld tegenover elkaar staan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren door het poortje van één van de tegenstanders.\nOpgelet:\n- het team dat scoort behoudt balbezit, maar mag niet tweemaal\nachter elkaar in hetzelfde doeltje scoren.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O11', 9, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\n- Kappen buitenkant voet (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.5 C: AANNEMEN-OPENEN, TOT 90º IN PLUSVORM (1)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal met de binnenkant van de rechtervoet\naan.\nC. Speler 1 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nD. Speler 3 dribbelt met de bal om de pylon naar speler 4\n- Speler 3 sluit achter speler 4 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\nIdem, met links aannemen en met links spelen.\nIdem, maar nu in tegengestelde richting uitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal pylonen: 5\nAantal ballen: 4\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(5 : 3) OEFENING 1", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 5:5", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om in één van de drie aan de overkant van\nhet vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 20m bij 25m\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-junioren: 35m bij 40m\nB-,A-junioren: 40m bij 45m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler).\n- het rekening houden met omschakeling bij\nbalverovering\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes (passeeractie of overspelen)\ngemaakt worden\n- het eventueel wisselen van tegenstander na\n10 minuten."}], "session_b": [{"type": "warming_up", "title": "KRUISPAS MET BAL", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek, in zijwaartse richting uitvoert(en).\nDe spelers) maakt(en), bij elke voorste voetplaatsing, een\nkruispas met de bal. De speler tikt daarbij de bal met de\nbinnenkant van de voet aan naar voren.\n1. Kruispas (Stap 3)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen gebruikt worden als de\nspeler stap 3 beheerst.\nDifferentiatie:\nBij elke achterste voetplaatsing de bal een tik naar voren geven.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aanpassen aan\nhoeveelheid spelers. Elke speler één bal.\nOrganisatie:\nUitvoering van de achterlijn naar de 16-\nmeterlijn. Dit kan je ook aangeven met pylonen.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nTRIPLING MET BAL\nMethodiek\nIs een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BUITEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 5B)\n- Akka (buiten-binnen) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie in uitvoering:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 5) en\nAkka (buiten-binnen) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wisselt, na de pass op speler 3, van\nplaats met speler 2. Vervolgens wisselt speler 3\nvan plaats met speler 1, nadat hij de oefening in\ntegenovergestelde richting en met het ander\nbeen heeft uitgevoerd, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "KOPPEN OP DOEL (2)", "content": "Bij deze oefening wordt de groep in tweeën gesplitst.\nA. Speler 1 gooit onderhands de bal aan op de inlopende speler 2.\nB. Speler 2 kopt de bal, met een één/tweebenige afzet, in het doel.\nWeerstand:\n- De keeper mag een makkelijke bal onderscheppen.\n- Inschakelen van een verdediger (van passief tot actief).\nVariatie:\n- Aangooiafstand vergroten\n- Aangooi van beide kanten van het doel.\nMaterialen\nAantal spelers: 6-8 + keeper\nAantal ballen: 3-4\nAantal pylonen: 2\nAantal doelen: 1\nOrganisatie:\nDe aangevers gooien de bal aan vanaf de\nachterlijn en de koppers koppen de bal vanaf de\n5-meterlijn op het doel door vanaf de 16-\nmeterlijn in te komen lopen.\nDoordraaien:\n- Speler 2 pakt de bal op en sluit achter in de rij\nvan de aangevers aan.\n- Speler 1 loopt nadat hij de bal gegooid heeft\ndoor en sluit achter in de rij van de koppende\nspelers aan, etc.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O11', 10, '{"session_a": [{"type": "warming_up", "title": "VOETBALROVERS", "content": "De spelers worden verdeeld in twee groepen, die aan weerszijden van het\nspeelveld tegenover elkaar staan. Aan beide zijden van het speelveld liggen\nevenveel ballen.\nDe groepen moeten proberen ongetikt naar de overkant zien te komen, een bal\nte pakken en weer terug te dribbelen.\nElke groep heeft daarbij 2 tikkers(in hesjes), die het overlopen moeten\nvoorkomen door onderweg zoveel mogelijk spelers van de andere groep te tikken.\nOpgelet!\nMen kan op de terugweg niet meer afgetikt worden.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen.\nAantal ballen: net zoveel als dat er spelers zijn"}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 4.\n- Speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- Idem, andersom met het andere been.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.3 C: DOORKOPPEN VANUIT EEN STAANDE POSITIE (1)", "content": "Staande oefening met 3-tallen, waarbij elke speler bij een pylon\nstaat.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 3\n- speler 2 kopt de bal schuin door , etc.\nVariatie in uitvoering:\n- idem, in tegengestelde richting met een aangooi vanaf de ander\nkant.\nMaterialen\nAantal spelers: 3\nAantal ballen: per drietal een bal\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-pupillen: 3 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht.\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- de kopbeweging moet ondersteund worden\nmet de armen en dient uit het hele\nbovenlichaam te komen (spanboog)\n- bal raken met het voorhoofd\n- de bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "TRIPLING MET BAL", "content": "Is een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSKIPPING MET BAL\nMethodiek\nIs een oefening, waarbij de speler de stappen van de\nonderstaande techniek, op de plaats, uitvoert, terwijl hij een bal in\nbeide handen voor zich houdt.Bij elke stap van de skipping raakt\nde speler bij het heffen van zijn knie met zijn bovenbeen de bal.\n1. Skipping (Stap 3 en 4)\nOpgelet!\n- dit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler de stappen 3 en 4 van de skipping beheerst.\nDifferentiatie:\n- uitvoering in voorwaartse richting.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\n- de spelers lopen van 5-meterlijn tot 16-\nmeterlijn in het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2, komt als tegenstander, ter hoogte van de middelste\nrechter pylon, inlopen op speler 1\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- 2x Kappen buitenkant voet (Stap 4B)\n- Pirouette (Stap 6B)\n- Aai- achter het standbeen (Stap 5B)\n- de Schijntrap (Stap 5B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 5), Kappen buitenkant voet (Stap 4), Pirouette\n(Stap 6) en De schijntrap (Stap 5).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wordt de tegenstander en neemt nadat\nhij de bal op speler 3 heeft gepassed de plaats in\nvan speler 2. Speler 2 neemt op zijn beurt de\nplaats in van speler1. Speler 3 heeft nu de bal en\nstart de oefening vervolgens, met het andere\nbeen, in tegenovergestelde richting, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "2. (4 : 2)", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 2\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "POORTJESVOETBAL 5 TEGEN 5", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van elk 5 spelers\ndie op een speelveld tegenover elkaar staan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren door het poortje van één van de tegenstanders.\nOpgelet:\n- het team dat scoort behoudt balbezit, maar mag niet tweemaal\nachter elkaar in hetzelfde doeltje scoren.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O11', 11, '{"session_a": [{"type": "warming_up", "title": "OVERSTEEK SPEL", "content": "Alle spelers staan met de bal aan de voet aan één kant van het\nveld en één speler staat zonder bal in het midden. Op een teken\nvan de trainer mogen de spelers proberen het veld over te steken.\nDe tikker moet vervolgens proberen de ballen van de spelers\nbuiten het veld te schieten.\nDe spelers van een weggeschoten bal gaan ook in het midden\nstaan om de bal af te pakken.\nVariatie:\n- De spelers moeten zelf hun weggetrapte bal ophalen en weer bij\nde groep aansluiten.\n- Weggeschoten bal ophalen en dan wachten om te zien wie er\nover blijft. De winnaar mag de nieuwe tikker zijn of aanwijzen.\n- Twee of meerdere afpakkers.\nMaterialen\nTijd: 10-15 min\nPylonen:\n4 pylonen om het speelveld uit te zetten.\n2 pylonen/hoedjes om de middenlijn uit te zetten.\nBallen: iedere speler een bal op de tikker na die\nde ballen gaat afpakken.\nAanwijzingen\n- Zorg dat de spelers de bal dicht bij zich\nhouden zodat ze de bal goed kunnen sturen.\n- Laat de spelers telkens op het teken van de\ntrainer starten."}, {"type": "techniek", "title": "STAP 2.6 C: KAATSEN-OPENEN, TOT 90º IN PLUSVORM (1)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 dribbelt met de bal om de pylon naar speler 4\n- Speler 3 sluit achter speler 4 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\nIdem, maar nu in tegengestelde richting uitvoeren en met links\nuitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal pylonen: 5\nAantal ballen: 4\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET WEERSTAND", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\n- Binnen-buitenkant wegdraai (Stap 5)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op de aanbiedende speler 2 te\npassen(deze heeft een verdediger, speler 3,in de rug).\nB. Speler 2 ontvangt de bal en passeert vervolgens met één van\nde bovengenoemde technieken de in zijn rug staande verdediger.\nC. Daarna dribbelt hij richting doel om vervolgens hierop af te\nronden.\nD. Speler 3 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 6,7,8,9 en 10 voeren dezelfde oefening uit op het\nandere doel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 neemt de taak over van speler 3.\n- Speler 3 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "techniek", "title": "NIET IN HET WATER 5 TEGEN 5", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 5 spelers, die\ntegen elkaar spelen.\nIn het veld staan 2 doelen met de achterkanten naar elkaar toe.\nTussen de doelen is een vak (water), waar geen spelers mogen\nkomen. De bal mg wel door het vak gespeeld worden.\nHet team dat scoort in het doel van de tegenstander krijgt 1 punt.\nOpgelet:\n- als een speler door het water loopt, krijgt de tegenstander een\nvrije bal op de achterlijn, aan de kant van het doel waar zij\nmoeten scoren.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 8\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "TRIPLING MET BAL", "content": "Is een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nKRUISPAS MET BAL\nMethodiek\nIs een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek, in zijwaartse richting uitvoert(en).\nDe spelers) maakt(en), bij elke voorste voetplaatsing, een\nkruispas met de bal. De speler tikt daarbij de bal met de\nbinnenkant van de voet aan naar voren.\n1. Kruispas (Stap 3)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen gebruikt worden als de\nspeler stap 3 beheerst.\nDifferentiatie:\nBij elke achterste voetplaatsing de bal een tik naar voren geven.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aanpassen aan\nhoeveelheid spelers. Elke speler één bal.\nOrganisatie:\nUitvoering van de achterlijn naar de 16-\nmeterlijn. Dit kan je ook aangeven met pylonen.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Sleep (Stap 4B)\n- Uitstappen meenemen (Stap 5B)\n- Akka (binnen-voor) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie in uitvoering:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 5), Sleep (Stap 4) en Akka (binnen-voor) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 wisselt, na de pass op speler 3, van\nplaats met speler 2. Vervolgens wisselt speler 3\nvan plaats met speler 1, nadat hij de oefening in\ntegenovergestelde richting en met het ander\nbeen heeft uitgevoerd, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O11', 12, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.7 B: AANNEMEN (MET HET BOVENBEEN) EN SPELEN TOT 45º (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op bovenbeenhoogte met een\nboog naar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met het bovenbeen aan en speelt de bal\ndirect met de binnenkant van de rechtervoet naar speler 3\nC. Speler 3 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 pakt de bal op en gooit de bal onderhands, op\nbovenbeenhoogte met een boog naar speler 2, etc\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nDeze oefenvorm geldt ook voor: Aannemen met de borst en met\nhet hoofd\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met het bovenbeen\nsoepel en flexibel met de bal meegaan en\nzodoende bal \"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.7 B: AANNEMEN (MET DE BORST) EN SPELEN TOT 45º (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op borsthoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met de borst aan en speelt de bal direct\nmet de binnenkant van de rechtervoet naar speler 3\nC. Speler 3 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 pakt de bal op en gooit de bal onderhands, op\nborsthoogte met een boog naar speler 2, etc\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nDeze oefenvorm geldt ook voor: Aannemen met het bovenbeen\nen met het hoofd\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met de borst soepel en\nflexibel met de bal meegaan en zodoende bal\n\"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(5 : 3) OEFENING 2", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "NIET IN HET WATER 5 TEGEN 5", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 5 spelers, die\ntegen elkaar spelen.\nIn het veld staan 2 doelen met de achterkanten naar elkaar toe.\nTussen de doelen is een vak (water), waar geen spelers mogen\nkomen. De bal mg wel door het vak gespeeld worden.\nHet team dat scoort in het doel van de tegenstander krijgt 1 punt.\nOpgelet:\n- als een speler door het water loopt, krijgt de tegenstander een\nvrije bal op de achterlijn, aan de kant van het doel waar zij\nmoeten scoren.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 8\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "test", "title": "SPEEDLADDER (3)", "content": "Is een oefening, waarbij de zijwaartse en voorwaartse vormen\nworden gecombineerd en aangeleerd in de speedladder. De\noefening is opgebouwd van grove motoriek naar de fijne motoriek.\nDat wil zeggen binnen de looptraining, er wordt gewerkt van een\nskipping naar skipping 45 graden en vervolgens naar kort\nvoetenwerk.\nStap 1: Twee voetjes in het raam plaatsen, één voetje eruit\nplaatsen.\nStap 2: Twee voetjes in het raam plaatsen, twee voetjes eruit\nplaatsen. (3 pasjes)\nStap 3: Eén voetjes in het raam plaatsen, twee voetjes eruit\nplaatsen. (kruisbeweging)\nLet op!\nDeze vormen kunnen pas worden aangeleerd wanneer\nspeedladder (1) en speedladder (2) beheerst worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 is de tegenstander en biedt daarbij passief weerstand\naan speler 1 door met hem mee op te lopen.\nB. Speler 1 maakt de beweging\n- De verandering (Stap 4B)\n- De Overstap (Stap 5B)\nC. Speler 1 speelt naar speler 3\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 3 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op!\nBij een inzet met de linkervoet over de bal, moet men ook met\nlinks dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n4) en De Overstap (Stap 5).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\n- Speler 1 wordt de tegenstander en neemt,\nnadat hij de bal op speler 3 heeft gepassed, de\nplaats in naast speler 3. Speler 3 heeft nu de bal\nen start de oefening vervolgens, met het andere\nbeen, in tegenovergestelde richting en neemt,\nnadat hij op zijn beurt de bal op speler 2 heeft\ngepassed, de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 is de tegenstander en biedt daarbij passief weerstand\naan speler 1 door met hem mee op te lopen.\nB. Speler 1 maakt de beweging\n- Kappen achter standbeen (Stap 3B)\n- Kappen binnenkant voet (Stap 4B)\n- Kappen buitenkant voet (Stap 4B)\nC. Speler 1 speelt naar speler 3\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 3 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op!\nBij een inzet met de linkervoet over de bal, moet men ook met\nlinks dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 4), Kappen buitenkant voet (Stap 4) en Kappen achter\nstandbeen (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\n- Speler 1 wordt de tegenstander en neemt,\nnadat hij de bal op speler 3 heeft gepassed, de\nplaats in naast speler 3. Speler 3 heeft nu de bal\nen start de oefening vervolgens, met het andere\nbeen, in tegenovergestelde richting en neemt,\nnadat hij op zijn beurt de bal op speler 2 heeft\ngepassed, de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O11', 13, '{"session_a": [{"type": "warming_up", "title": "PAALTJES VOETBAL 2", "content": "Het spel wordt gespeeld met tweetallen, elk met 1 pylon en een\nbal. De ene speler is verdediger en de ander aanvaller. De\naanvaller moet proberen 1 punt te scoren door de pylon omver te\nschieten. De verdediger probeert dit te voorkomen.\nOpgelet!\n- Na een aantal minuten wisselen van functie.\n- De spelers moeten binnen het afgebakende veld blijven.\nVariatie:\nBij een score wisselen alle spelers tegelijk van functie\nMaterialen\nDuur:10-15 min\nAantal: 2 of meer spelers\nPylon: voor ieder tweetal 1\nBallen: 1-2\nAanwijzingen\nZorg dat de spelers niet voor de pylon blijven\nhangen."}, {"type": "techniek", "title": "STAP 2.5 C: AANNEMEN-OPENEN, TOT 90º IN PLUSVORM (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal met de binnenkant van de rechtervoet\naan.\nC. Speler 1 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nD. Speler 3 dribbelt met de bal om de pylon naar speler 8\n- Speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- Idem, met links aannemen en met links spelen.\n- Idem, maar nu in tegengestelde richting uitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: MET WEERSTAND", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4B)\n- Pirouette (Stap 6B)\n- Aai-kappen achter het standbeen (Stap 5B)\n- Schijntrap (Stap 5B)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan komt een tegenstander (speler 2) vanaf de\nzijkant op hem inlopen. Hij passeert vervolgens de tegenstander\nmet één van de bovengenoemde technieken.\nC. Daarna controleert hij de bal en rond vervolgens af op het doel.\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan en\nspeler 1 neemt de taak over van speler 2.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Speler 1 neemt de taak over van speler 2, etc.\n- Idem aan de andere kant.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 + 2 KEEPERS", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\n- met 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nD-pupillen: 35m bij 30m\nC-junioren: 40m bij 35m\nB-,A-junioren: 45m bij 40m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (ANDERE)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA.Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 biedt daarbij passief weerstand door langzaam op hem\naf te komen lopen.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 5B)\n- Akka (binnen-buiten) (Stap 3B)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 5) en Akka (binnen-buiten) (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 komt, na de pass op speler 3, op een\nplaats te staan schuin tegenover speler 3.\nVervolgens neemt speler 2 de plaats in van\nspeler 1. Speler 3 voert nu de oefening, met het\nander been, in tegenovergestelde richting uit,\nenz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nOPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD\nMethodiek\nD.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O11', 14, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 B: INGOOIEN, AANBIEDEN, TOT 45º IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"naar links\" aan.\n- Speler 1 gooit de bal in.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich opengedraaid \"naar links\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\n- Speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 1\n- Idem als beschreven bij A, etc.\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten.\n1. (3 : 1 + 2)\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "techniek", "title": "KANTELEN VOETBAL 5 TEGEN 5", "content": "Deze oefening wordt uitgevoerd met 2 teams van elk 5 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 14\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 3 komt, als tegenstander, ter hoogte van het midden van\nde middelste pylonen inlopen op speler 2.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen- buitenkant wegdraai (Stap 5)\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar de overkant.\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 5),\nKappen buitenkant voet (Stap 4) en Binnen buiten wegdraai (Stap\n5).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\n- Speler 1 blijft, na de pass op speler 2, staan.\nSpeler 2 dribbelt naar de plek ter hoogte van de\noverstaande pylonen en neemt de plek van\nspeler 3 in. Speler 3 gaat in het midden staan.\n- Speler 2 voert nu de oefening, met het ander\nbeen, in tegenovergestelde richting uit, enz..\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.3 C: DOORKOPPEN VANUIT EEN STAANDE POSITIE (1)", "content": "Staande oefening met 3-tallen, waarbij elke speler bij een pylon\nstaat.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 3\n- speler 2 kopt de bal schuin door , etc.\nVariatie in uitvoering:\n- idem, in tegengestelde richting met een aangooi vanaf de ander\nkant.\nMaterialen\nAantal spelers: 3\nAantal ballen: per drietal een bal\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-pupillen: 3 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht.\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- de kopbeweging moet ondersteund worden\nmet de armen en dient uit het hele\nbovenlichaam te komen (spanboog)\n- bal raken met het voorhoofd\n- de bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O11', 15, '{"session_a": [{"type": "warming_up", "title": "SNIJ TIKKERTJE", "content": "Eén speler probeert als tikker de andere spelers te tikken. De\ntikker moet, als een andere speler de achtervolging doorkruist,\nvan achtervolgde wisselen. Hij moet nu de andere speler gaan\nachtervolgen.\nOpgelet!\n- naar eigen inzicht wisselen van tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- een getikte wordt de nieuwe tikker.\n- de tikker bepaald van te voren wie hij gaat\ntikken.\n- dit spel kan verwarring veroorzaken. Houd\nde lijn van kruisen goed in de gaten."}, {"type": "techniek", "title": "STAP 2.6 C: KAATSEN-OPENEN, TOT 90º IN PLUSVORM (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 dribbelt met de bal om de pylon naar speler 8\n- Speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\nIdem, maar nu in tegengestelde richting uitvoeren en met links\nuitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(5 : 3) OEFENING 1", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 5:5", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om in één van de drie aan de overkant van\nhet vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 20m bij 25m\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-junioren: 35m bij 40m\nB-,A-junioren: 40m bij 45m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler).\n- het rekening houden met omschakeling bij\nbalverovering\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes (passeeractie of overspelen)\ngemaakt worden\n- het eventueel wisselen van tegenstander na\n10 minuten."}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "IN STROOMVORM (2)", "content": "Deze oefenvorm wordt uitgevoerd met twee groepen binnen een\nafgebakend vak.\nA. Speler 1 passed de bal, schuin over de breedte, op de vragende\nspeler 2.\nB. Speler 2 krijgt de bal zodanig en met de juiste snelheid\naangespeeld, dat hij hem direct op het doel kan schieten.\nOpgelet!\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\n- Idem andersom met het andere been.\n- Vergroot/verklein de afstand ten opzichte van het schietpunt en/\nof het vak.\nMaterialen\nAantal spelers: 8- 12\nAantal ballen: 4-6\nAantal pylonen: 6\nBreedte speelveld: 20m\nDoelen: 2\nF-,E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen:\nStartafstand vanaf doel:\n2e jaars F-pupillen: 11 m\n1e jaars E-pupillen: 13 m\n2e jaars E-pupillen: 15 m\nD-pupillen: 17 m\nC-,B-,A-junioren: >19 m\nSchietafstand vanaf doel:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Nadat de speler geschoten heeft haalt hij zijn\neigen bal op en sluit achter in de andere rij aan.\n- Nadat een speler de beginpass heeft gegeven\nsluit hij aan in de rij aan de andere zijde van het\ndoel.\nAanwijzingen\nSpelers coachen op:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "techniek", "title": "KANTELEN VOETBAL 5 TEGEN 5", "content": "Deze oefening wordt uitgevoerd met 2 teams van elk 5 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 14\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O11', 16, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.7 B: AANNEMEN (MET HET BOVENBEEN) EN SPELEN TOT 45º (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op bovenbeenhoogte met een\nboog naar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met het bovenbeen aan en speelt de bal\ndirect met de binnenkant van de rechtervoet naar speler 3\nC. Speler 3 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 pakt de bal op en gooit de bal onderhands, op\nbovenbeenhoogte met een boog naar speler 2, etc\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nDeze oefenvorm geldt ook voor: Aannemen met de borst en met\nhet hoofd\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met het bovenbeen\nsoepel en flexibel met de bal meegaan en\nzodoende bal \"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.7 B: AANNEMEN (MET DE BORST) EN SPELEN TOT 45º (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op borsthoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met de borst aan en speelt de bal direct\nmet de binnenkant van de rechtervoet naar speler 3\nC. Speler 3 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 pakt de bal op en gooit de bal onderhands, op\nborsthoogte met een boog naar speler 2, etc\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nDeze oefenvorm geldt ook voor: Aannemen met het bovenbeen\nen met het hoofd\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met de borst soepel en\nflexibel met de bal meegaan en zodoende bal\n\"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (2)", "content": "Is een oefening, waarbij de zijwaartse vormen worden aangeleerd\nover de stokken. De oefening is opgebouwd van grove motoriek\nnaar de fijne motoriek. Dat wil zeggen binnen de looptraining, er\nwordt gewerkt van een skipping naar skipping 45 graden en\nvervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de andere stokken worden gelopen met één voet\ntussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden zijwaarts genomen en vervolgens wordt er met\ntwee voeten teruggestapt, de andere stokken worden gelopen\nmet één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden zijwaarts genomen en vervolgens\nwordt er met twee voeten teruggestapt, de andere stokken\nworden gelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 is de tegenstander en biedt daarbij passief weerstand\naan speler 1 door met hem mee op te lopen.\nB. Speler 1 maakt de beweging\n- De verandering (Stap 4B)\n- De Overstap (Stap 5B)\nC. Speler 1 speelt naar speler 3\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 3 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op!\nBij een inzet met de linkervoet over de bal, moet men ook met\nlinks dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n4) en De Overstap (Stap 5).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\n- Speler 1 wordt de tegenstander en neemt,\nnadat hij de bal op speler 3 heeft gepassed, de\nplaats in naast speler 3. Speler 3 heeft nu de bal\nen start de oefening vervolgens, met het andere\nbeen, in tegenovergestelde richting en neemt,\nnadat hij op zijn beurt de bal op speler 2 heeft\ngepassed, de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\n- Speler 2 is de tegenstander en biedt daarbij passief weerstand\naan speler 1 door met hem mee op te lopen.\nB. Speler 1 maakt de beweging\n- Kappen achter standbeen (Stap 3B)\n- Kappen binnenkant voet (Stap 4B)\n- Kappen buitenkant voet (Stap 4B)\nC. Speler 1 speelt naar speler 3\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 3 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op!\nBij een inzet met de linkervoet over de bal, moet men ook met\nlinks dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 4), Kappen buitenkant voet (Stap 4) en Kappen achter\nstandbeen (Stap 3).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\n- Speler 1 wordt de tegenstander en neemt,\nnadat hij de bal op speler 3 heeft gepassed, de\nplaats in naast speler 3. Speler 3 heeft nu de bal\nen start de oefening vervolgens, met het andere\nbeen, in tegenovergestelde richting en neemt,\nnadat hij op zijn beurt de bal op speler 2 heeft\ngepassed, de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (2 : 1)", "content": "REGELS:\n• Twee aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• Direct na verovering van de bal moet de verdediger wisselen\nvan taak met de aanvaller van wie hij de bal heeft veroverd.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 3\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het vrijlopen en aanspeelbaar zijn, zonder\nbal\n• het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n• het altijd in beweging zijn van de bal en de\nspeler\n• het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n• het vragen om de bal\n• het nacoachen van de bal/ pass\nVERDEDIGER COACHEN OP:\n• het rekening houden met een goed zicht op\nde posities van de aanvallers\n• het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\nPOORTJESVOETBAL 5 TEGEN 5\nMethodiek\nDeze oefenvorm wordt uitgevoerd met 2 teams van elk 5 spelers\ndie op een speelveld tegenover elkaar staan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren door het poortje van één van de tegenstanders.\nOpgelet:\n- het team dat scoort behoudt balbezit, maar mag niet tweemaal\nachter elkaar in hetzelfde doeltje scoren.\nMaterialen\nAantal spelers: 10\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O11', 17, '{"session_a": [{"type": "warming_up", "title": "FLUIT / NUMMERSPEL", "content": "Elke speler dribbelt met een bal door het vak. De trainer gebruikt de vooraf aan\ngegeven tekens.\nBij het fluiten of het roepen van een nummer moeten de spelers de daarbij\nbehorende afgesproken tekens uitvoeren, zoals:\n- Naar de zijkant dribbelen\n- Een kapbeweging maken\n- De bal stil leggen onder de voet\n- Een versnelling maken met de bal aan de voet\n- De bal hooghouden.\n- Op de bal zitten\n- Wisselen van bal met een andere speler.\nOpgelet!\nMaak er een puntenspel van.\nWie behaalt de minste strafpunten?\nMaterialen\nTijd: 10-15 min\nRonde tijden: 1 a 2 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: iedere speler heeft een bal."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 4.\n- speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel.\nTEGENSTANDER VOOR JE: IN EEN Y-VORM\nMethodiek\nDe onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Speler 1 voert de \"Aai-buitenkantvoet\" (Stap 5A) uit.\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O11', 18, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN EEN PLUSVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nVariatie:\nEen dubbele schaarbeweging door 2x om de bal heen te bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN EEN PLUSVORM (BUITEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nVariatie:\nEen dubbele schaarbeweging door 2x om de bal heen te bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET KAATSER (2)", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Schaar (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB.Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 de bal op de doorgelopen speler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog.\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O11', 19, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\nAannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- Naar rechts\n- Naar links\n- Achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nWisselen door in de andere rij aan te sluiten.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 A: KOPPEN (RECHT) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 staat en speler 2 op de\nknieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal recht terug , etc.\nVariatie in uitvoering:\n- zittende speler speelt de bal met kracht terug op de staande\nspeler en eindigt daarbij languit met zijn buik op de grond.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal recht aangegooid en\nwordt daardoor gedwongen om de bal ook\nrecht terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "UIT DE RUG", "content": "Oefeningen, waarbij de spelers voor elkaar staan. De voorste speler staat hierbij\nin een vak van 2 bij 3 meter.\nDe achterste speler probeert, door plotseling te versnellen, uit de rug van de\nvoorste speler te komen en zonder getikt te worden de finishlijn te behalen.\nOpgelet!\nHet is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\nLater, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 6\nAantal ballen: 0\nOrganisatie:\nDe spelers staan voor elkaar. Bij deze oefening ligt het initiatief ligt bij de\nachterste speler."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN PLUSVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 4A)\n- Kappen binnenkant (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening uit.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 geeft de bal aan speler 2 enz.\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O11', 20, '{"session_a": [{"type": "warming_up", "title": "LIJNEN SPEL", "content": "De spelers staan met de bal aan de voet op een door de trainer\naangegeven lijn van het 16- meter gebied. Op zijn teken dribbelen\nde spelers naar een door de trainer aangegeven andere lijn.\nOpgelet!\nGeen 16- meter gebied beschikbaar, maak dan gebruik van\nverschillend gekleurde pylonen of hoedjes om daarmee lijnen te\nvormen\nMaak bij de\" jongste jeugd\" gebruik van nummers.\nVariatie:\n- Geef elke speler bij aanvang 3 punten en haal bij de laatste\ntelkens 1 punt af. Winnaar is ook nu weer degene die over blijft.\n- Laatste valt steeds af en winnaar is degene die over blijft (alleen\ndoen als afsluiting van een training).\nMaterialen\nAantal spelers: 4-14\nAantal pylonen: 10 (om eventueel de lijnen aan\nte geven)\nAantal ballen: elke speler 1 bal\nAanwijzingen\nSpelers coachen op:\n- Draai eerst proef.\n- De bal moet wel steeds op de lijn onder de\nvoet stil liggen."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (2)", "content": "Is een oefening, waarbij de zijwaartse vormen worden aangeleerd\nover de stokken. De oefening is opgebouwd van grove motoriek\nnaar de fijne motoriek. Dat wil zeggen binnen de looptraining, er\nwordt gewerkt van een skipping naar skipping 45 graden en\nvervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de andere stokken worden gelopen met één voet\ntussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden zijwaarts genomen en vervolgens wordt er met\ntwee voeten teruggestapt, de andere stokken worden gelopen\nmet één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden zijwaarts genomen en vervolgens\nwordt er met twee voeten teruggestapt, de andere stokken\nworden gelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN PLUSVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- 2x kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- de Schijntrap (Stap 5A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu, met het andere been, in\ntegengestelde richting dezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nIdem voor de spelers 4,5 en 6.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen: 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr. tot de\nmiddelste pylon\nDoordraaien:\n- Speler 1 geeft de bal aan speler 2. Deze speler\nvoert de oefening met het andere been in\ntegenovergestelde richting uit en geeft de bal\naan speler 3. Enz.\n- Idem voor de spelers 4,5 en 6.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O11', 21, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º (ZELFDE/ANDERE BEEN) IN RUITVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "SPEEDLADDER (3)", "content": "Is een oefening, waarbij de zijwaartse en voorwaartse vormen\nworden gecombineerd en aangeleerd in de speedladder. De\noefening is opgebouwd van grove motoriek naar de fijne motoriek.\nDat wil zeggen binnen de looptraining, er wordt gewerkt van een\nskipping naar skipping 45 graden en vervolgens naar kort\nvoetenwerk.\nStap 1: Twee voetjes in het raam plaatsen, één voetje eruit\nplaatsen.\nStap 2: Twee voetjes in het raam plaatsen, twee voetjes eruit\nplaatsen. (3 pasjes)\nStap 3: Eén voetjes in het raam plaatsen, twee voetjes eruit\nplaatsen. (kruisbeweging)\nLet op!\nDeze vormen kunnen pas worden aangeleerd wanneer\nspeedladder (1) en speedladder (2) beheerst worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN LIJNVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 6\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 6.\nIdem voor de spelers 4,5 en 6 in tegengestelde richting, etc.\nVariatie:\nIdem, maar nu met het andere been uitvoeren.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 3\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar speler 6 en geeft\nhem de bal. Speler 4 neemt, na de pass op\nspeler 5, diens plaats in en speler 5 geeft de bal\naan speler 3, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\n- Binnen-buitenkant wegdraai (Stap 4)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op speler 2 te passen (deze doet alsof hij\neen speler in de rug heeft).\nB. Speler 2 ontvangt de bal en voert vervolgens één van de\nbovengenoemde technieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 3 en loopt\ndoor om de bal te ontvangen\nD. Vervolgens kaatst speler 3 de bal terug op de doorgelopen\nspeler 2.\nE. Speler 2 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 3 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 neemt de taak over van speler 3\n- Speler 3 haalt de bal en sluit achter in de\nandere rij aan.\nIdem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\nBal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O11', 22, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- idem, met rechts aannemen en met links spelen.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 A: KOPPEN (RECHT) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 staat en speler 2 op de\nknieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal recht terug , etc.\nVariatie in uitvoering:\n- zittende speler speelt de bal met kracht terug op de staande\nspeler en eindigt daarbij languit met zijn buik op de grond.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal recht aangegooid en\nwordt daardoor gedwongen om de bal ook\nrecht terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BUITEN)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 5A) en\nAkka (buiten-binnen) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- Het moment waarop je de beweging inzet is\nafhankelijk van de snelheid van het dribbelen\n(eerder of later inzetten).\n- Je mag de tegenstander, bij de uitvoering\nvan de oefening, niet raken."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O11', 23, '{"session_a": [{"type": "warming_up", "title": "KRISKRASORGANISATIE (1)", "content": "Spelers voeren één van de stappen van de onderstaande\ntechnieken uit, terwijl zij met de bal aan de voet , zonder elkaar te\nhinderen, door het hele vak bewegen.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\nSpelers staan kris kras door elkaar.\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN X-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- idem, andersom oefening met links uitvoeren\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 135º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP TIKKERTJE", "content": "Bij deze oefening staan de spelers verdeeld in 2 groepen van elk 6 spelers\ntegenover elkaar aan beide zijden van het “stokken-parcours”.\nAan het eind van beide parcoursen staan twee verschillend gekleurde pylonen\nmet aan weerszijden op 10 meter afstand daarvan nog een pylon.\nEr wordt tegelijkertijd gestart met het stokkenparcours(foutloos lopen, anders\nopnieuw).\nDe eerste aangekomene tikt een pylon aan en kiest vervolgens een richting.\nDe laatst aangekomene moet nadat hij de pylon heeft aangetikt de ander\nproberen in te halen en te tikken.\nLet op!\nBij beheersing van het stokkenparcours kan er op snelheid wordt gewerkt.\nMaterialen\nAantal spelers: 12\nAantal pylonen: 24\nOrganisatie:\nDe spelers staan tegenover elkaar met een ruimte er tussen van 20 á 25 meter.\nDe onderlinge afstanden van het stokkenparcours moet even groot zijn."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 5A), Sleep (Stap 4A) en Akka (binnen-voor) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O11', 24, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 4\n- Speler 4 biedt zich \"naar links\"aan.\n- Speler 3 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 4.\nD. Speler 4 speelt naar speler 1\n- Idem als beschreven bij B, etc.\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "1. (2 : 1)", "content": "REGELS:\n• Twee aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• Direct na verovering van de bal moet de verdediger wisselen\nvan taak met de aanvaller van wie hij de bal heeft veroverd.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 3\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het vrijlopen en aanspeelbaar zijn, zonder\nbal\n• het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n• het altijd in beweging zijn van de bal en de\nspeler\n• het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n• het vragen om de bal\n• het nacoachen van de bal/ pass\nVERDEDIGER COACHEN OP:\n• het rekening houden met een goed zicht op\nde posities van de aanvallers\n• het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- De verandering (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op! Bij een inzet met de linkervoet over de bal, moet men ook\nmet links dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n4A) en De Overstap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening in\ntegenovergestelde richting uit en passed de bal\nop zijn beurt weer op speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 kaats de bal op de doorgelopen\nspeler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O11', 25, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN RUIT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- Idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- Idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- Idem, met rechts aannemen en met links spelen.\n- Idem, andersom met het andere been.\nVariatie in aanbieden:\n- Naar links\n- Voorwaarts\n- Achterwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 B: KOPPEN (SCHUIN) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 schuin t.o.v. speler 2 staat\nen speler 2 op de knieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu de aangooi vanaf de andere kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n- 1e jaars E-pupillen: 2 m\n- 2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan, op een onderlinge afstand van 2 meter. Aan de ene\nkant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\néén van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- als de speler de ander voor de vrije zone\nkan tikken dan heeft die een punt. Speel een\npotje tot de vijf.\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer er een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen, dus\nspelen met de ''rrrrr''."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 3.\n- Speler 1 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 5A),\nKappen buitenkant voet (Stap 4A) en Binnen buiten wegdraai\n(Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar de plek ter\nhoogte van de overstaande pylonen en geeft\ndaar de bal aan speler 3. Deze speler start de\noefening opnieuw, maar nu in tegengestelde\nrichting, door de bal op de doorgelopen speler 1\nte spelen, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O11', 26, '{"session_a": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 180º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "PAALTJES VOETBAL 2", "content": "Het spel wordt gespeeld met tweetallen, elk met 1 pylon en een\nbal. De ene speler is verdediger en de ander aanvaller. De\naanvaller moet proberen 1 punt te scoren door de pylon omver te\nschieten. De verdediger probeert dit te voorkomen.\nOpgelet!\n- Na een aantal minuten wisselen van functie.\n- De spelers moeten binnen het afgebakende veld blijven.\nVariatie:\nBij een score wisselen alle spelers tegelijk van functie\nMaterialen\nDuur:10-15 min\nAantal: 2 of meer spelers\nPylon: voor ieder tweetal 1\nBallen: 1-2\nAanwijzingen\nZorg dat de spelers niet voor de pylon blijven\nhangen."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai achter standbeen (Stap 5A)\n- De Schijntrap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan en voert nu, met het andere been, in tegengestelde richting\ndezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 5A), Kappen buitenkant voet (Stap 4A), Pirouette\n(Stap 6A) en De schijntrap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 passed de bal op speler 2. Deze speler\nvoert de oefening in de tegenovergestelde\nrichting met het andere been uit en passed de\nbal op speler 3. Enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O11', 27, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(4 : 2) OEFENING 3", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdedigers moeten na het veroveren van de bal op de kleine\ndoeltjes scoren (omschakeling).\nWisselen van taak:De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nKleine doelen: 2x (3m bij 1m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "KRUISPAS MET BAL", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek, in zijwaartse richting uitvoert(en).\nDe spelers) maakt(en), bij elke voorste voetplaatsing, een\nkruispas met de bal. De speler tikt daarbij de bal met de\nbinnenkant van de voet aan naar voren.\n1. Kruispas (Stap 3)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen gebruikt worden als de\nspeler stap 3 beheerst.\nDifferentiatie:\nBij elke achterste voetplaatsing de bal een tik naar voren geven.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aanpassen aan\nhoeveelheid spelers. Elke speler één bal.\nOrganisatie:\nUitvoering van de achterlijn naar de 16-\nmeterlijn. Dit kan je ook aangeven met pylonen.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Kappen achter standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op! Bij een inzet met de linkervoet over de bal, moet men ook\nmet links dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 4A), Kappen buitenkant voet (Stap 4A) en Kappen\nachter standbeen (Stap 3A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening in\ntegenovergestelde richting uit en passed de bal\nop zijn beurt weer op speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 kaats de bal op de doorgelopen\nspeler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O11', 28, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\nAannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- Naar rechts\n- Naar links\n- Achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nWisselen door in de andere rij aan te sluiten.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 B: KOPPEN (SCHUIN) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 schuin t.o.v. speler 2 staat\nen speler 2 op de knieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu de aangooi vanaf de andere kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n- 1e jaars E-pupillen: 2 m\n- 2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (ANDERE)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 5A) en Akka (binnen-buiten) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O11', 29, '{"session_a": [{"type": "warming_up", "title": "OVERSTEEK SPEL", "content": "Alle spelers staan met de bal aan de voet aan één kant van het\nveld en één speler staat zonder bal in het midden. Op een teken\nvan de trainer mogen de spelers proberen het veld over te steken.\nDe tikker moet vervolgens proberen de ballen van de spelers\nbuiten het veld te schieten.\nDe spelers van een weggeschoten bal gaan ook in het midden\nstaan om de bal af te pakken.\nVariatie:\n- De spelers moeten zelf hun weggetrapte bal ophalen en weer bij\nde groep aansluiten.\n- Weggeschoten bal ophalen en dan wachten om te zien wie er\nover blijft. De winnaar mag de nieuwe tikker zijn of aanwijzen.\n- Twee of meerdere afpakkers.\nMaterialen\nTijd: 10-15 min\nPylonen:\n4 pylonen om het speelveld uit te zetten.\n2 pylonen/hoedjes om de middenlijn uit te zetten.\nBallen: iedere speler een bal op de tikker na die\nde ballen gaat afpakken.\nAanwijzingen\n- Zorg dat de spelers de bal dicht bij zich\nhouden zodat ze de bal goed kunnen sturen.\n- Laat de spelers telkens op het teken van de\ntrainer starten."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 180º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (2)", "content": "Is een oefening, waarbij de zijwaartse vormen worden aangeleerd\nover de stokken. De oefening is opgebouwd van grove motoriek\nnaar de fijne motoriek. Dat wil zeggen binnen de looptraining, er\nwordt gewerkt van een skipping naar skipping 45 graden en\nvervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de andere stokken worden gelopen met één voet\ntussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden zijwaarts genomen en vervolgens wordt er met\ntwee voeten teruggestapt, de andere stokken worden gelopen\nmet één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden zijwaarts genomen en vervolgens\nwordt er met twee voeten teruggestapt, de andere stokken\nworden gelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 3.\n- Speler 1 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 5A),\nKappen buitenkant voet (Stap 4A) en Binnen buiten wegdraai\n(Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar de plek ter\nhoogte van de overstaande pylonen en geeft\ndaar de bal aan speler 3. Deze speler start de\noefening opnieuw, maar nu in tegengestelde\nrichting, door de bal op de doorgelopen speler 1\nte spelen, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O11', 30, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(4 : 2) OEFENING 3", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdedigers moeten na het veroveren van de bal op de kleine\ndoeltjes scoren (omschakeling).\nWisselen van taak:De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nKleine doelen: 2x (3m bij 1m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "AANBIEDEN, TOT 135º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O11', 31, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- idem, met rechts aannemen en met links spelen.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 B: KOPPEN (SCHUIN) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 schuin t.o.v. speler 2 staat\nen speler 2 op de knieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu de aangooi vanaf de andere kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n- 1e jaars E-pupillen: 2 m\n- 2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai achter standbeen (Stap 5A)\n- De Schijntrap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan en voert nu, met het andere been, in tegengestelde richting\ndezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 5A), Kappen buitenkant voet (Stap 4A), Pirouette\n(Stap 6A) en De schijntrap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 passed de bal op speler 2. Deze speler\nvoert de oefening in de tegenovergestelde\nrichting met het andere been uit en passed de\nbal op speler 3. Enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (2 : 1)", "content": "REGELS:\n• Twee aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• Direct na verovering van de bal moet de verdediger wisselen\nvan taak met de aanvaller van wie hij de bal heeft veroverd.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 3\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het vrijlopen en aanspeelbaar zijn, zonder\nbal\n• het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n• het altijd in beweging zijn van de bal en de\nspeler\n• het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n• het vragen om de bal\n• het nacoachen van de bal/ pass\nVERDEDIGER COACHEN OP:\n• het rekening houden met een goed zicht op\nde posities van de aanvallers\n• het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O11', 32, '{"session_a": [{"type": "warming_up", "title": "SIGNAAL SPEL", "content": "Alle spelers staan met een bal naast elkaar in één rij voor de\ntrainer. Vooraf spreekt de trainer met de spelers bepaalde tekens\naf. Op een teken van de trainer voeren de spelers bijbehorende\nopdracht uit.\nVoorbeelden zijn:\n- dribbelen op de plaats door de bal links rechts te tikken\n- dribbelen naar links of rechts.\n- voor uit of achteruit te dribbelen.\n- voeten beurtlinks links rechts op de bal zetten.\n- etc.\nMaterialen\nTijd: 10-15 min\nPylonen: gebruik hiervoor de ruimte die u voor u\ntraining ter beschikking heeft.\nBallen: voor iedere speler een bal.\nAanwijzingen\n- zorg dat elke speler voldoende ruimte heeft\nvoor het uitvoeren van de oefening.\n- houdt controle over de bal. Let er op dat de\nspelers de bal dichtbij zich houden.\n- doe eerst oefeningen zonder bal."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 180º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP TIKKERTJE", "content": "Bij deze oefening staan de spelers verdeeld in 2 groepen van elk 6 spelers\ntegenover elkaar aan beide zijden van het “stokken-parcours”.\nAan het eind van beide parcoursen staan twee verschillend gekleurde pylonen\nmet aan weerszijden op 10 meter afstand daarvan nog een pylon.\nEr wordt tegelijkertijd gestart met het stokkenparcours(foutloos lopen, anders\nopnieuw).\nDe eerste aangekomene tikt een pylon aan en kiest vervolgens een richting.\nDe laatst aangekomene moet nadat hij de pylon heeft aangetikt de ander\nproberen in te halen en te tikken.\nLet op!\nBij beheersing van het stokkenparcours kan er op snelheid wordt gewerkt.\nMaterialen\nAantal spelers: 12\nAantal pylonen: 24\nOrganisatie:\nDe spelers staan tegenover elkaar met een ruimte er tussen van 20 á 25 meter.\nDe onderlinge afstanden van het stokkenparcours moet even groot zijn."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- De verandering (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op! Bij een inzet met de linkervoet over de bal, moet men ook\nmet links dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n4A) en De Overstap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening in\ntegenovergestelde richting uit en passed de bal\nop zijn beurt weer op speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb)
